 private ItemStack[] items={ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY};private java.util.UUID key=java.util.UUID.randomUUID();private int cornerX,cornerZ,activation,channelLevel;private ChannelList channels=ChannelList.EMPTY;private boolean physical,inert,pending,dirty,inputReady;private volatile Visual cachedVisual;private CompoundTag retained=new CompoundTag();
