 public void samplePower(){if(!(level instanceof ServerLevel)||!NativeBuilderFormation.loaded(level,worldPosition))return;boolean next=false;if(formed()){var d=design();for(int x=0;x<d.width();x++)for(int y=0;y<d.height();y++)for(int z=0;z<d.depth();z++){var p=cell(x,y,z);if(NativeBuilderFormation.loaded(level,p)&&level.hasNeighborSignal(p))next=true;}}if(next!=physical){physical=next;changed();}}
 public static void tick(net.minecraft.world.level.Level l,BlockPos p,BlockState s,NativeBuilderEntity t){if(!t.available())return;t.runtime.tick();if(t.dirty&&l.getGameTime()%5==0){t.dirty=false;l.sendBlockUpdated(p,s,s,2);}}
 @Override public boolean isChannelMemberActive(){return !inert&&NativeChannelMember.super.isChannelMemberActive();}@Override public BlockEntity channelBlockEntity(){return this;}@Override public ChannelList getRedstoneChannels(){return channels;}@Override public void setChannelLevel(int value){if(channelLevel!=value){channelLevel=value;changed();}}@Override public void beforeChannelRegistration(){Runnable ready=()->{samplePower();inputReady=true;};if(NativeSignalUpdateBatch.isActive())NativeSignalUpdateBatch.afterSignals(this,ready);else ready.run();}@Override public void onLoad(){inputReady=false;super.onLoad();if(level instanceof ServerLevel)NativeRedstoneChannels.queueRegistration(this);}@Override public void setRemoved(){if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);super.setRemoved();}@Override public void onChunkUnloaded(){if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);super.onChunkUnloaded();}
 public boolean canUse(Player p){return !transactionBlocked()&&canKeepUse(p);}
