 @Override public int getContainerSize(){return 4;}@Override public boolean isEmpty(){for(var i:items)if(!i.isEmpty())return false;return true;}@Override public ItemStack getItem(int slot){return slot>=0&&slot<4?items[slot]:ItemStack.EMPTY;}@Override public ItemStack removeItem(int slot,int count){if(!available()||slot<0||slot>3)return ItemStack.EMPTY;var out=items[slot].split(Math.max(0,count));if(!out.isEmpty())changed();return out;}@Override public ItemStack removeItemNoUpdate(int slot){if(!available()||slot<0||slot>3)return ItemStack.EMPTY;var out=items[slot];items[slot]=ItemStack.EMPTY;changed();return out;}@Override public void setItem(int slot,ItemStack stack){if(!available()||slot<0||slot>3)return;items[slot]=stack;changed();}@Override public boolean stillValid(Player p){return formed()&&canUse(p);}@Override public void clearContent(){if(!available())return;java.util.Arrays.fill(items,ItemStack.EMPTY);changed();}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){if(stack.isEmpty())return false;var id=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();return slot==0?id.equals("vandorlabs:programmable_matter_block"):slot==2?NativeBatteryModule.valid(stack):slot==3&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.accepts(stack,true);}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider r){tag.merge(retained.copy());if(inert){com.vandorlabs.neoforge.NativePlatformComponents.clearForInertSave(this);return;}super.saveAdditional(tag,r);tag.putUUID("BuilderKey",key);tag.putInt("ConstructorCoreX",cornerX);tag.putInt("ConstructorCoreZ",cornerZ);tag.putInt("Activation",activation);tag.putIntArray("Channels",channels.toArray());tag.put("Inventory",NativeBuilderData.save(items,r));var work=new CompoundTag();runtime.save(work);tag.put("Synthesis",work);}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider r){if(level!=null&&level.isClientSide&&tag.getBoolean("BuilderPublic")){readPublic(tag);return;}inputReady=false;cachedVisual=null;var original=tag.copy();try{
  com.vandorlabs.neoforge.NativePlatformComponents.requireSupported(original,r);if(tag.contains("ForgeCaps")&&(!tag.contains("ForgeCaps",Tag.TAG_COMPOUND)||!tag.getCompound("ForgeCaps").isEmpty()))throw new IllegalArgumentException("Unsupported legacy Builder capabilities");
  if(tag.contains("Inventory")&&!tag.contains("Inventory",Tag.TAG_COMPOUND)||tag.contains("Synthesis")&&!tag.contains("Synthesis",Tag.TAG_COMPOUND)||tag.contains("Channels")&&!tag.contains("Channels",Tag.TAG_INT_ARRAY)||tag.contains("BuilderKey")&&!tag.hasUUID("BuilderKey"))throw new IllegalArgumentException("Builder saved field types");for(var k:java.util.List.of("ConstructorCoreX","ConstructorCoreZ","Activation"))if(tag.contains(k)&&!tag.contains(k,Tag.TAG_INT))throw new IllegalArgumentException("Builder coordinate/settings types");
  var next=NativeBuilderData.read(tag.getCompound("Inventory"),r);int x=tag.getInt("ConstructorCoreX"),z=tag.getInt("ConstructorCoreZ"),mode=tag.getInt("Activation");if(x!=0&&x!=design().width()-1||z!=0&&z!=design().depth()-1||mode<0||mode>2)throw new IllegalArgumentException("Builder layout snapshot");var nextChannels=ChannelList.of(tag.getIntArray("Channels"));var stagedWork=new NativeSynthesisRuntime(this);stagedWork.read(tag.getCompound("Synthesis"));
  try(var guard=com.vandorlabs.neoforge.NativePlatformComponents.guardLoad(this)){super.loadAdditional(original,r);guard.requireSuccessful();}
  runtime.read(tag.getCompound("Synthesis"));items=next;cornerX=x;cornerZ=z;activation=mode;channels=nextChannels;if(tag.hasUUID("BuilderKey"))key=tag.getUUID("BuilderKey");inert=false;retained=original;for(var k:java.util.List.of("id","x","y","z","BuilderKey","ConstructorCoreX","ConstructorCoreZ","Activation","Channels","Inventory","Synthesis","BuilderPublic","BuilderInert"))retained.remove(k);com.vandorlabs.neoforge.NativePlatformComponents.forgetLoadedFields(retained);
 }catch(RuntimeException bad){inert=true;retained=original;java.util.Arrays.fill(items,ItemStack.EMPTY);runtime.read(new CompoundTag());}}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider r){var tag=new CompoundTag();tag.putBoolean("BuilderPublic",true);tag.putUUID("BuilderKey",key);tag.putBoolean("BuilderInert",inert);tag.putInt("ConstructorCoreX",cornerX);tag.putInt("ConstructorCoreZ",cornerZ);tag.putInt("Activation",activation);tag.putIntArray("Channels",channels.toArray());tag.putInt("BatteryCharge",batteryEnergy());tag.putBoolean("BatteryPresent",!items[2].isEmpty());tag.putInt("ChipCompany",items[3].isEmpty()?-1:com.vandorlabs.neoforge.credentials.NativeCredentialItems.company(items[3]));int output=-1;for(int i=0;i<3;i++)if(!items[1].isEmpty()&&items[1].getItem()==NativeBuilderBindings.CORES.get(NativeBuilderDesigns.at(i).id()).asItem())output=i;tag.putInt("Output",output);var work=new CompoundTag();runtime.save(work);tag.put("Synthesis",work);return tag;}
 private void readPublic(CompoundTag tag){cachedVisual=null;try{if(tag.hasUUID("BuilderKey"))key=tag.getUUID("BuilderKey");cornerX=tag.getInt("ConstructorCoreX");cornerZ=tag.getInt("ConstructorCoreZ");activation=Math.max(0,Math.min(2,tag.getInt("Activation")));channels=ChannelList.of(tag.getIntArray("Channels"));runtime.read(tag.getCompound("Synthesis"));items=new ItemStack[]{ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY};int output=tag.getInt("Output");if(output>=0&&output<3)items[1]=NativeSynthesisRuntime.result(output);if(tag.getBoolean("BatteryPresent")){items[2]=new ItemStack(com.vandorlabs.neoforge.rack.NativeRackBindings.BATTERY);NativeBatteryModule.transfer(items[2],Math.max(0,Math.min(NativeBatteryModule.CAPACITY,tag.getInt("BatteryCharge"))),false,true);}int company=tag.getInt("ChipCompany");if(company>=0&&company<7)items[3]=com.vandorlabs.neoforge.credentials.NativeCredentialItems.dataChip(company);inert=tag.getBoolean("BuilderInert");}catch(RuntimeException malformed){inert=true;java.util.Arrays.fill(items,ItemStack.EMPTY);}}
